# Write JSONL
data_dir = Path("data")
data_dir.mkdir(exist_ok=True, parents=True)

with open(data_dir / "nodes.jsonl", "w", encoding="utf-8") as f:
    for n in nodes:
        f.write(json.dumps(n, ensure_ascii=False) + "\n")

with open(data_dir / "edges.jsonl", "w", encoding="utf-8") as f:
    for e in edges:
        f.write(json.dumps(e, ensure_ascii=False) + "\n")

print(f"Generated data/nodes.jsonl: {len(nodes)} nodes")
print(f"Generated data/edges.jsonl: {len(edges)} edges")
